// Package copygen is every word the server shows a reader: Discord bot replies and embeds, push
// notifications, email and the app sign-in page. The constants are generated by
// web/scripts/gen-mobile-copy.mjs from apps/shared/copy (en.json, the apps' words; shared.json,
// the words the site shows too; server.json, the server's own), so one key reads the same on the
// site, both apps, Discord, push and email. Never edit a *_gen.go file: edit the JSON and run
// `node web/scripts/gen-mobile-copy.mjs`.
//
// A text's {name} markers are filled with Fill; a Plural picks its form with For.
package copygen

import (
	"strconv"
	"strings"
)

// Fill replaces each marker with its value: Fill("{Name} is In.", "{Name}", "Ashenveil").
// pairs alternate marker and value, the way strings.NewReplacer takes them.
func Fill(text string, pairs ...string) string {
	return strings.NewReplacer(pairs...).Replace(text)
}

// Plural is a counted text: One for a count of one, Other (which shows {Count}) for the rest.
type Plural struct {
	// Count is the placeholder the count fills, without braces.
	Count string
	// One and Other are the two forms.
	One, Other string
}

// For is the form for n with the count filled in: "1 kill", "3 kills".
func (p Plural) For(n int) string {
	form := p.Other
	if n == 1 {
		form = p.One
	}
	return Fill(form, "{"+p.Count+"}", strconv.Itoa(n))
}
